def _skip_ws(text: str, pos: int) -> int:
    # Fast path: skip large chunks of whitespace using str.find
    if pos + 10 < len(text):  # Only do fast path for reasonably long skips
        try:
            # Find the next non-whitespace character
            next_non_ws = text.index(next((c for c in text[pos:] if c not in _WS_CHARS), None))
            return pos + next_non_ws
        except ValueError:
            # No non-whitespace found, skip to end
            return len(text)
    # Fall back to the original loop for small skips or when fast path fails
    while pos < len(text) and text[pos] in _WS_CHARS:
        pos += 1
